// Lee la configuracion de data/config.csv (clave,valor).
// Vive en un fichero y no en el flujo: se cambia sin tocar el flujo.
const config = {};
for (const item of $('Parsear configuracion').all()) {
  const clave = String(item.json?.clave ?? '').trim();
  const valor = String(item.json?.valor ?? '').trim();
  if (clave) config[clave] = valor;
}
// Clasifica los apartados activos en tres grupos (HU-06 y HU-07):
//   - los que hay que recordar (su plazo vence dentro de los dias de aviso)
//   - los que ya estan fuera de plazo y hay que vencer
//   - los demas
//
// Los dias de aviso vienen de la variable DIAS_AVISO_VENCIMIENTO (7 y 1 por defecto).
// Ningun importe se recalcula: pendiente y fecha_limite son los de la API.
// Los apartados vienen del nodo que los pidio a la API (este nodo recibe la
// configuracion, que va por delante).
const apartados = $('Apartados activos').all()
  .flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json]))
  .filter((a) => a && a.id !== undefined);

const hoy = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Madrid', year: 'numeric', month: '2-digit', day: '2-digit',
}).format(new Date());

// Los dias de aviso salen del fichero de configuracion (data/config.csv).
const diasAviso = String(config.DIAS_AVISO_VENCIMIENTO || '7,1')
  .split(',').map((n) => Number(String(n).trim())).filter((n) => Number.isFinite(n));

const diasQueFaltan = (fechaLimite) => Math.round(
  (new Date(String(fechaLimite) + 'T00:00:00Z').getTime() - new Date(hoy + 'T00:00:00Z').getTime()) / 86400000,
);

const recordatorios = [];
const vencimientos = [];
for (const a of apartados) {
  if (!a.fecha_limite) continue;
  const dias = diasQueFaltan(a.fecha_limite);
  if (diasAviso.includes(dias)) recordatorios.push({ apartado: a, dias, clave: a.id + ':' + dias });
  else if (dias < 0) vencimientos.push({ apartado: a, dias, clave: a.id + ':vencido' });
}

return [{ json: { hoy, apartados: apartados.length, recordatorios, vencimientos } }];

// Un recordatorio por cliente cuyo plazo vence dentro de los dias de aviso.
//
// El mensaje lleva lo que falta por pagar y la fecha limite: los datos de la API.
// Si ese recordatorio ya se envio otro dia, se salta (regla A6).
const clasificacion = $('Clasificar apartados').first().json ?? {};

// Los avisos que ya se han enviados se guardan en los datos estaticos del flujo
// (memoria de n8n entre ejecuciones), para no avisar dos veces al mismo cliente.
const staticData = $getWorkflowStaticData('global');
staticData.avisos = Array.isArray(staticData.avisos) ? staticData.avisos : [];
const enviados = new Set(staticData.avisos.map((k) => String(k)));

const euros = (n) => Number(n ?? 0).toFixed(2).replace('.', ',') + ' EUR';
const escapar = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const salida = [];
const nuevos = [];
for (const r of (clasificacion.recordatorios ?? [])) {
  if (enviados.has(r.clave)) continue;
  const a = r.apartado;
  const cuando = r.dias === 1 ? 'mañana' : 'dentro de ' + r.dias + ' días';
  const cuerpo = [
    'Hola ' + (a.cliente ?? '') + ',',
    '',
    'Tu apartado de ' + [a.producto, a.talla].filter(Boolean).join(' · ') + ' vence ' + cuando + ' (' + (a.fecha_limite ?? '') + ').',
    '',
    'Te queda por pagar: ' + euros(a.pendiente),
    'Abonado: ' + euros(a.abonado),
    'Fecha limite: ' + (a.fecha_limite ?? ''),
    '',
    'Si no lo terminas antes de la fecha, los zapatos vuelven a la tienda y lo abonado',
    'se convierte en un vale de compra. Puedes venir cuando quieras a pagar el resto.',
    '',
    'Gracias!',
    'Zapateria Paso Firme',
  ].join('\n');

  nuevos.push(r.clave);
  salida.push({
    json: {
      canal: 'email',
      email: String(a.email ?? '').trim(),
      asunto: 'Tu apartado vence ' + cuando,
      cuerpo,
      cuerpo_html: '<p>' + escapar(cuerpo).replace(/\n/g, '<br>') + '</p>',
      // Cifras que la redaccion tiene que mantener: se comprueban despues.
      cifras: [euros(a.pendiente)],
      clave: r.clave,
      apartado_id: a.id,
    },
  });
}

return salida;

// Actualiza el historico de recordatorios enviados.
// Se escribe DESPUES de enviar, y con la clave 'apartado:dias' para que el
// mismo cliente no reciba dos veces el aviso del mismo plazo.
// Las claves son las del nodo que preparo los recordatorios (el de envio devuelve
// el resultado de la notificacion, sin la clave).
const nuevos = $('Preparar recordatorios').all().map((i) => i.json?.clave).filter(Boolean);

// Se guardan en los datos estaticos del flujo: la memoria de n8n entre ejecuciones.
const staticData = $getWorkflowStaticData('global');
staticData.avisos = Array.isArray(staticData.avisos) ? staticData.avisos : [];
const todos = Array.from(new Set([...staticData.avisos.map(String), ...nuevos.map(String)]));
staticData.avisos = todos;

return [{ json: { avisos: todos, nuevos: nuevos.length } }];

// Apartados que ya estan fuera de plazo: hay que vencerlos por API.
// La app genera el vale; n8n solo avisa.
const clasificacion = $('Clasificar apartados').first().json ?? {};
return (clasificacion.vencimientos ?? []).map((v) => ({
  json: {
    apartado_id: v.apartado.id,
    cliente: v.apartado.cliente,
    producto: v.apartado.producto,
    talla: v.apartado.talla,
    precio: v.apartado.precio,
    abonado: v.apartado.abonado,
    pendiente: v.apartado.pendiente,
    fecha_limite: v.apartado.fecha_limite,
    dias: v.dias,
  },
}));

// La API devuelve el apartado vencido y su vale.
// Si no se ha podido vencer (por ejemplo, alguien lo ha pagado antes), no se avisa
// de un vale que no existe.
const r = $input.first().json ?? {};
const apartado = r.apartado ?? null;
const vale = r.vale ?? null;

if (!apartado || !vale) {
  return [{ json: { vencido: false, detalle: String(r.detail ?? r.message ?? 'No se ha podido vencer el apartado') } }];
}

return [{
  json: {
    vencido: true,
    apartado,
    vale,
    detalle: 'Apartado #' + apartado.id + ' vencido con el vale ' + vale.codigo,
  },
}];

// Comprueba que la redaccion del modelo mantiene todas las cifras del aviso.
//
// Si el modelo ha cambiado, redondeado o inventado un importe, se usa el texto
// original: el tono lo pone el modelo, las cifras las pone la tienda.
const entrada = $input.first().json ?? {};
const original = String(entrada.cuerpo ?? '');
const cifras = entrada.cifras ?? [];

const redactado = String(entrada.text ?? entrada.output ?? '').trim();
const normalizar = (t) => String(t).replace(/\s/g, '').replace(',', '.');

const faltan = cifras.filter((c) => !normalizar(redactado).includes(normalizar(c)));

const cuerpo = redactado && faltan.length === 0 ? redactado : original;

return [{
  json: {
    ...entrada,
    cuerpo,
    cuerpo_html: '<p>' + String(cuerpo).replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/\n/g, '<br>') + '</p>',
    redaccion: redactado && faltan.length === 0 ? 'aceptada' : 'original',
    cifras_faltantes: faltan,
  },
}];
